// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 targetBlock) public {
        vm.assume(caller != address(0));
        uint256 b = bound(targetBlock, block.number + 1, block.number + 1000);

        vm.deal(caller, 20 ether);

        vm.roll(b);
        vm.warp(block.timestamp + 1);

        vm.prank(caller);
        (bool ok, ) = payable(address(c)).call{value: 10 ether}('');
        bool notDrained = (b % 15) != 0 ? (address(c).balance >= 10 ether) : true;
        assertTrue(notDrained);
    }
}
